import{_ as s,a0 as n,w as a,s as i,ao as d,I as p,x as e,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"USB4 規範獲得最終批准，像以太網一樣快！ | LCTT x X-CMD","titleTemplate":false,"description":"USB4 規範獲得最終批准，像以太網一樣快！ | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"USB4 規範獲得最終批准，像以太網一樣快！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"USB4 規範獲得最終批准，像以太網一樣快！ | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190905 USB4 gets final approval, offers Ethernet-like speed","title":"USB4 規範獲得最終批准，像以太網一樣快！","tag":"201909","desc":""},"relativePath":"201909/20190905 USB4 gets final approval, offers Ethernet-like speed.md","filePath":"[post].md"}'),u={name:"201909/20190905 USB4 gets final approval, offers Ethernet-like speed.md"};function S(U,t,B,f,m,T){const r=n("Link");return a(),i("div",null,[t[15]||(t[15]=d('<h1 id="usb4-規範獲得最終批准-像以太網一樣快" tabindex="-1">USB4 規範獲得最終批准，像以太網一樣快！ <a class="header-anchor" href="#usb4-規範獲得最終批准-像以太網一樣快" aria-label="Permalink to “USB4 規範獲得最終批准，像以太網一樣快！”">​</a></h1><blockquote><p>USB4 會是一個統一的接口，可以淘汰笨重的電纜和超大的插頭，並提供滿足從筆記本電腦用户到服務器管理員的每個人的吞吐量。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/thunderbolt-3_intel-v2-100790083-large.jpg" alt=""></p><p><ruby>USB 開發者論壇<rt>USB Implementers Forum</rt></ruby>（USB-IF）是通用串行總線（USB）規範開發背後的行業協會，上週宣佈了它已經完成了下一代 USB4 的技術規範。</p><p>USB4 最重要的一個方面（它們在此版本中省略了首字母縮略詞和版本號之間的空格）是它將 USB 與 Intel 設計的接口 Thunderbolt 3 融合在了一起。Thunderbolt 儘管有潛力，但在除了筆記本之外並未真正流行起來。出於這個原因，Intel 向 USB 聯盟提供了 Thunderbolt 規範。</p><p>不幸的是，Thunderbolt 3 被列為 USB4 設備的一個可選項，因此有些設備會有，有些則不會。這無疑會讓人頭疼，希望所有設備製造商都會包括 Thunderbolt 3。</p><p>USB4 將使用與 USB type-C 相同的外形尺寸，這個小型插頭用在所有現代 Android 手機和 Thunderbolt 3 中。它將向後兼容 USB 3.2、USB 2.0 以及 Thunderbolt。因此，幾乎任何現有的USB type-C 設備都可以連接到具有 USB4 總線的機器，但將以連接電纜的額定速度運行。</p><h3 id="usb4-體積更小-速度更快" tabindex="-1">USB4：體積更小，速度更快 <a class="header-anchor" href="#usb4-體積更小-速度更快" aria-label="Permalink to “USB4：體積更小，速度更快”">​</a></h3><p>因為它支持 Thunderbolt 3，所以這種新連接將同時支持數據和顯示協議，因此這可能意味着小型 USB-C 端口將取代顯示器上龐大的 DVI 端口，而顯示器則帶有多個 USB4 端口來作為集線器。</p><p>新標準的主要內容：它提供雙通道 40Gbps 傳輸速度，是當前 USB 3.2 規格的兩倍，是 USB 3 的八倍。這是以太網的速度，應該足夠給你的高清顯示器以及其他數據傳輸提供充足帶寬。</p><p>USB4 也為視頻提供了更好的資源分配，因此如果你使用 USB4 端口同時傳輸視頻和數據，端口將相應地分配帶寬。這將允許計算機同時使用外部獨立的 GPU（因為有 Thunderbolt 3，它已經上市 ）和外部 SSD。</p><p>這可能會啓發各種新的服務器設計，因為大型、笨重的設備，如 GPU 或其他不易放入 1U 或 2U 機箱的卡板，現在可以外部連接並以與內部設備相當的速度運行。</p><p>當然，我們看到配備了 USB4 端口的電腦還需要一段時間，更別説服務器了。將 USB 3 用於 PC 花費了數年時間，而 USB-C 的採用速度非常緩慢。USB 2 的 U 盤仍然是這些設備的主要市場，並且主板仍然帶有 USB 2 端口。</p><p>儘管如此，USB4 還是有可能成為一個統一的接口，可以擺脱擁有超大插頭的笨重電纜，並提供滿足從筆記本電腦用户到服務器管理員的每個人的吞吐量。</p><hr>',15)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),l(r,{href:"https://www.networkworld.com/article/3435113/usb4-gets-final-approval-offers-ethernet-like-speed.html"},{default:o(()=>[...t[0]||(t[0]=[e("https://www.networkworld.com/article/3435113/usb4-gets-final-approval-offers-ethernet-like-speed.html",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),l(r,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:o(()=>[...t[2]||(t[2]=[e("Andy Patrizio",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),l(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),l(r,{href:"https://github.com/geekpi"},{default:o(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),l(r,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const C=s(u,[["render",S]]);export{h as __pageData,C as default};
